17. 다음 자바 코드에 적용된 디자인 패턴은?
public class DesignManager {
private DesignManager() { }
private static DesignManager _instance = null;
public synchronized
static DesignManager Instance() {
if (_instance == null)
_instance = new DesignManager();
return _instance;
}
}
